import{_ as i}from"./chunks/Audio.COine8Wh.js";import{_ as r}from"./chunks/Tags.BJ536pW3.js";import{c as n,o,j as t,G as a,ae as s,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"SUPPORT for Patients and Communities Reauthorization Act of 2025","description":"","frontmatter":{"legisId":"2025-12-01-support-for-patients-and-communities-reauthorization-act-of-2025","title":"SUPPORT for Patients and Communities Reauthorization Act of 2025","displayTitle":"SUPPORT for Patients and Communities Reauthorization Act of 2025","lawNumber":"119-44","billNumber":"H.R. 2483","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ44.xml","publishDate":"2025-12-01T00:00:00-05:00","industries":["healthcare","education","labor"],"agencies":["Department of Health and Human Services","Administration for Community Living","Food and Drug Administration","Substance Abuse and Mental Health Services Administration"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"SUPPORT for Patients and Communities Reauthorization Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-01-support-for-patients-and-communities-reauthorization-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"SUPPORT for Patients and Communities Reauthorization Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-01-support-for-patients-and-communities-reauthorization-act-of-2025\\",\\"datePublished\\":\\"2025-12-01T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-01-support-for-patients-and-communities-reauthorization-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-12-01-support-for-patients-and-communities-reauthorization-act-of-2025.md","filePath":"congress-bills/2025-12-01-support-for-patients-and-communities-reauthorization-act-of-2025.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2025-12-01-support-for-patients-and-communities-reauthorization-act-of-2025.md"},f=Object.assign(d,{setup(c){return(p,e)=>(o(),n("div",null,[e[0]||(e[0]=t("h1",{id:"support-for-patients-and-communities-reauthorization-act-of-2025",tabindex:"-1"},[l("SUPPORT for Patients and Communities Reauthorization Act of 2025 "),t("a",{class:"header-anchor",href:"#support-for-patients-and-communities-reauthorization-act-of-2025","aria-label":'Permalink to "SUPPORT for Patients and Communities Reauthorization Act of 2025"'},"​")],-1)),a(i),a(r,{list:"/congress-bills"}),e[1]||(e[1]=s('<p>Signed into law on Monday, December 1, 2025. Public Law 119-44, H.R. 2483.</p><p><strong>Headline:</strong> The law renews and expands federal prevention, treatment, and recovery programs for substance use disorders, overdoses, mental illness, and trauma.</p><p><strong>Why it matters:</strong> It funds major health programs through fiscal year 2030, broadens opioid-focused efforts to address other dangerous substances, and improves access to treatment, recovery support, professional training, and drug-safety information.</p><p><strong>What the law does:</strong></p><ul><li>Funds maternal and child health, overdose prevention, fetal alcohol spectrum disorder services, first-responder training, trauma programs, and suicide-prevention protections through 2030.</li><li>Expands treatment funding, workforce grants and loan repayment, trauma-informed care, and state guidance for early serious mental illness and first-episode psychosis.</li><li>Renews recovery, peer-support, youth, employment, transportation, and recovery-housing programs while improving access to federal funding information.</li><li>Requires reviews and guidance on opioid pain medicines, nonaddictive alternatives, buprenorphine-naloxone scheduling, overdose-reversal drugs, at-home drug disposal, and electronic health records.</li><li>Strengthens 988 Suicide Prevention Lifeline cybersecurity and permits privacy-compliant wastewater surveillance and lawful fentanyl and xylazine test-strip support.</li><li>Expands pharmacy delivery rules for certain controlled drugs administered by practitioners and broadens approved prescriber-training providers and programs.</li></ul><p><strong>Who it affects:</strong></p><ul><li>People at risk of overdose, suicide, trauma, serious mental illness, or substance use disorder, including pregnant and postpartum women and young people.</li><li>First responders, treatment and recovery providers, peer-support workers, schools, pharmacies, prescribers, states, Tribes, and community organizations.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Patients and families may gain broader access to prevention, treatment, overdose-reversal, recovery, crisis, and maternal-health services.</li><li>People in recovery may receive more help with peer support, housing, employment, training, and transportation connected to treatment or work.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="title-i-prevention" tabindex="-1">TITLE I, PREVENTION <a class="header-anchor" href="#title-i-prevention" aria-label="Permalink to &quot;TITLE I, PREVENTION&quot;">​</a></h3><p>Title I funds and updates federal prevention programs addressing maternal and child health, overdoses, fetal alcohol spectrum disorders, trauma, suicide prevention, and drug safety. It broadens several opioid-focused efforts to cover other overdose-causing substances, strengthens education and surveillance, and requires new cybersecurity, reporting, guidance, and assessment activities.</p><p><strong>Key takeaways:</strong></p><ul><li>The title authorizes funding for fiscal years 2026 through 2030 for prenatal and postnatal health, overdose prevention, fetal alcohol spectrum disorder services, first responder training, child trauma programs, and trauma monitoring.</li><li>Overdose prevention grants may support rapid detection of changing drug-use patterns and associated risks, including evidence-based wastewater surveillance that complies with privacy laws.</li><li>A comprehensive fetal alcohol spectrum disorder program will support education, research, screening, diagnosis, interventions, services, professional training, technical assistance, and State and Tribal capacity.</li><li>States retain the choice of vendors and interoperability connections for prescription drug monitoring programs, subject to nationally recognized open standards.</li><li>The title strengthens the National Child Traumatic Stress Initiative and requires cybersecurity protections and incident reporting for the 988 Suicide Prevention Lifeline, along with a federal study of its cybersecurity risks.</li><li>The title expands fentanyl and synthetic-opioid education, creates a federal interagency work group on fentanyl-contaminated illegal drugs, requires guidance on at-home drug disposal, directs the FDA to assess opioid pain medicines and nonaddictive alternatives, and allows certain grants to support fentanyl and xylazine test strips where lawful.</li></ul><h3 id="title-ii-treatment" tabindex="-1">TITLE II, TREATMENT <a class="header-anchor" href="#title-ii-treatment" aria-label="Permalink to &quot;TITLE II, TREATMENT&quot;">​</a></h3><p>This title expands and updates federal treatment programs for substance use disorders and serious mental health conditions. It increases or extends support for treatment facilities, workforce programs, trauma-informed care, and state mental health services, while directing federal reviews and guidance on medications, overdose-reversal drugs, and electronic health records.</p><p><strong>Key takeaways:</strong></p><ul><li>The title provides $38.931 million annually from fiscal years 2026 through 2030 for residential treatment programs serving pregnant and postpartum women and allows applicants to describe outreach to women disproportionately affected by maternal substance use disorder.</li><li>It includes addiction diagnosis and addiction medicine in relevant workforce programs, extends mental and behavioral health education grants through fiscal year 2030, and provides $40 million annually through fiscal year 2030 for substance use disorder workforce loan repayment.</li><li>It adds the Administration for Community Living and developmental disability service providers to the federal trauma-informed care task force and extends the task force through 2030.</li><li>It requires a federal review of how states use community mental health block grant funds for early serious mental illness and first-episode psychosis, followed by a report, recommendations, and updated state guidance.</li><li>It requires review of the federal controlled-substance scheduling of approved products combining buprenorphine and naloxone and directs federal opioid grant materials to cover all approved or authorized overdose-reversal drugs rather than naming only naloxone.</li><li>It requires a public roundtable and congressional report on expanding electronic health record use among mental health and substance use providers, including adoption barriers, costs, care coordination, information exchange, and links to crisis-response systems.</li></ul><h3 id="title-iii-recovery" tabindex="-1">TITLE III, RECOVERY <a class="header-anchor" href="#title-iii-recovery" aria-label="Permalink to &quot;TITLE III, RECOVERY&quot;">​</a></h3><p>This title renews and expands federal programs supporting substance use disorder recovery, youth prevention, peer support, workforce services, recovery housing, and communities affected by the opioid crisis. It authorizes increased funding for several programs through 2030, updates eligibility and reporting rules, and permits a regional peer-support technical assistance center. It also requires federal action to make information about Substance Abuse and Mental Health Services Administration funding opportunities easier to find and use.</p><p><strong>Key takeaways:</strong></p><ul><li>The title authorizes $17 million annually from 2026 through 2030 for Building Communities of Recovery and $2 million annually for the Peer Support Technical Assistance Center.</li><li>The Department of Health and Human Services may establish one regional peer-support technical assistance center using existing resources, must evaluate it within four years, and must end its authority after September 30, 2030.</li><li>Comprehensive opioid recovery centers using referrals or contracts must document their ability to provide required services and report whether those arrangements are working.</li><li>The youth prevention and recovery program is expanded to include secondary schools and school consortia, requires sustainability plans, and receives increasing authorized funding from $10 million in 2026 to $15 million in 2030.</li><li>The CAREER Act and recovery housing pilot are extended through 2030, use updated overdose and labor-market data, and allow up to 5 percent of grant funds for transportation tied to work, training, treatment, or recovery.</li><li>The Department of Health and Human Services must hold a public meeting, improve access to information about SAMHSA funding opportunities where feasible, and report to Congress on resulting website and outreach improvements.</li></ul><h3 id="title-iv-miscellaneous-matters" tabindex="-1">TITLE IV, MISCELLANEOUS MATTERS <a class="header-anchor" href="#title-iv-miscellaneous-matters" aria-label="Permalink to &quot;TITLE IV, MISCELLANEOUS MATTERS&quot;">​</a></h3><p>This title expands when a pharmacy may deliver certain controlled drugs to the prescribing practitioner for administration to a patient. It also broadens the organizations, schools, and professional education programs that may provide or satisfy required controlled-substance prescriber training, including those related to family medicine, podiatry, pharmacy, optometry, dentistry, and nursing.</p><p><strong>Key takeaways:</strong></p><ul><li>A pharmacy may deliver a Schedule III, IV, or V drug to the prescribing practitioner when the drug will be injected or implanted for maintenance or detoxification treatment.</li><li>Delivery is also allowed when the drug has a federally required safety program that includes post-administration monitoring by a health care provider.</li><li>The title recognizes additional professional organizations and accrediting bodies as eligible providers or approvers of required prescriber training.</li><li>Podiatric medicine curricula and accredited schools of pharmacy are added as ways to satisfy applicable training requirements.</li><li>The prescriber-training changes take effect as though enacted on December 29, 2022.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ44.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ44.xml</a></p>',27))]))}});export{g as __pageData,f as default};
